from snapshot.ignore import ignored_files
NAMES = ['a','b','ab','ba','a.c','.a','aa','a b','x','.packignore']
def mutate_seg(r, seg):
    out = []
    i = 0
    for c in seg:
        x = r.random()
        if x < 0.15: out.append('*')
        elif x < 0.25: out.append('?')
        elif x < 0.3: out.append('**')
        else: out.append(c)
    if r.random() < 0.15: out.insert(r.randint(0,len(out)), '*')
    return ''.join(out)
def gen_pat(r, paths):
    p = r.choice(paths).split('/')
    k = r.randint(1, len(p)); start = r.randint(0, len(p)-k)
    segs = p[start:start+k]
    segs = [mutate_seg(r, s) if r.random()<0.5 else s for s in segs]
