cd /tmp/probe && python3 -c "
import unicodedata as u
N=u.normalize
cands = {
 'cf(NFC)': lambda s: N('NFC',s).casefold(),
 'NFC(cf)': lambda s: N('NFC',s.casefold()),
 'cf(NFD)': lambda s: N('NFD',s).casefold(),
 'NFD(cf)': lambda s: N('NFD',s.casefold()),
 'NFC(cf(NFC))': lambda s: N('NFC',N('NFC',s).casefold()),
 'NFD(cf(NFD))': lambda s: N('NFD',N('NFD',s).casefold()),
}
pairs=set()
for i in range(0x80,0x20000):
  if 0xd800<=i<0xe000: continue
  c=chr(i)
  for d in {c.casefold(), N('NFC',c.casefold()), N('NFD',c.casefold()), N('NFD',c), N('NFC',c)}:
    if d==c: continue
    sig=tuple(f(c)==f(d) for f in cands.values())
    if len(set(sig))>1: pairs.add((sig,c,d))
bysig={}
for sig,c,d in sorted(pairs):
  bysig.setdefault(sig,[]).append((c,d))
print(list(cands))
for sig,v in bysig.items(): print(sig, len(v), ascii(v[:3]))
"

